ruleBookInfo.intro:
@js:
var s = String(result || '').replace(/\r/g, '');
var out = '';
var i = s.indexOf('小说简介');
if (i < 0) i = s.indexOf('内容简介');
if (i > -1) {
  s = s.substring(i);
  var p = s.indexOf('</p>');
  if (p > -1) s = s.substring(p + 4);
  var ends = ['<div align="center"', '<div class="pageMainArea"', '<script'];
  for (var n = 0; n < ends.length; n++) {
    var j = s.indexOf(ends[n]);
    if (j > -1) s = s.substring(0, j);
  }
  out = s.replace(/<br\s*\/?>/ig, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&raquo;/g, '').replace(/^[\s\n]+/, '').replace(/[\s\n]+$/, '');
}
out;

ruleContent.content:
@js:
var u0 = String(baseUrl || '');
var mp = /[?&]part=(\d+)/.exec(u0);
var out = '';
if (mp) {
  var mn = /[?&]n=(\d+)/.exec(u0);
  var mc = /[?&]ch=(\d+)/.exec(u0);
  var idx = parseInt(mp[1], 10);
  var tot = mn ? parseInt(mn[1], 10) : 1;
  var ch = mc ? parseInt(mc[1], 10) : 500000;
  var base = u0.replace(/[?&](part|n|ch)=[^&]*/g, '').replace(/\?$/, '');
  var a = idx * ch;
  var b = (idx + 1 >= tot) ? '' : String((idx + 1) * ch - 1);
  try { out = String(java.ajax(base + ',{"headers":{"Range":"bytes=' + a + '-' + b + '"}}')); } catch (e) { out = ''; }
}
if (!out) { out = String(result || ''); }
var s = out;
if (s.substr(0, 2) === 'PK' && s.charCodeAt(2) === 3) {
  s = '【压缩包】本站在该书上架较早，只提供 ZIP 压缩包，阅读器无法解压。请复制本章链接用浏览器下载后用「本地导入」：' + u0;
} else {
  s = s.replace(/<br\s*\/?>/ig, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&raquo;/g, '').replace(/&amp;/g, '&').replace(/\ufeff/g, '');
  s = s.replace(/推荐一个小说下载必备网址[^\n]*/g, '').replace(/每天更新，喜欢的去看看。[^\n]*/g, '');
  s = s.replace(/\r/g, '').replace(/\u3000\u3000/g, '\n').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n');
  s = s.replace(/^[\s\n]+/, '').replace(/[\s\n]+$/, '');
}
result = s;
s

ruleToc.chapterList:
@js:
var h = String(result || '');
var re = /<a[^>]*href="(https?:\/\/[^"]+\.txt)"[^>]*>([^<]*)<\/a>/gi, m, u = '';
while ((m = re.exec(h))) { if (String(m[2]).indexOf('在线阅读') < 0) { u = m[1]; break; } }
if (!u) { var r2 = /<a[^>]*href="(https?:\/\/[^"]+\.txt)"/i.exec(h); if (r2) { u = r2[1]; } }
var sp = /小说大小[\s\S]{0,60}?([0-9]+(?:\.[0-9]+)?)\s*(M|K|G)B/i.exec(h);
var sz = 0;
if (sp) { var un = String(sp[2]).toUpperCase(); sz = parseFloat(sp[1]) * (un === 'M' ? 1048576 : (un === 'K' ? 1024 : 1073741824)); }
if (sz > 0) { sz = sz * 0.97; }
var arr = [];
if (u && /\.txt/i.test(u)) {
  if (!(sz > 0)) { sz = 3145728; }
  var CH = 500000;
  var n = Math.ceil(sz / CH);
  if (n < 1) { n = 1; }
  if (n > 40) { CH = Math.ceil(sz / 40); n = Math.ceil(sz / CH); }
  for (var i = 0; i < n; i++) {
    arr.push({'ChapterName': '第' + (i + 1) + '部分/共' + n + '部分', 'ChapterUrl': u + '?part=' + i + '&n=' + n + '&ch=' + CH});
  }
} else if (u) {
  arr.push({'ChapterName': '压缩包(ZIP)', 'ChapterUrl': u});
}
if (arr.length === 0) { arr.push({'ChapterName': '全文', 'ChapterUrl': ''}); }
result = arr;
arr
